def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    last_my, last_opp = history[-1]
    my_def = 0
    opp_def = 0
    for my, opp in history:
        if my == 'D':
            my_def += 1
        if opp == 'D':
            opp_def += 1
    if last_opp == 'C':
        return 'C'
    if my_def == 0:
        return 'D'
    opp_coop = n - opp_def
    if opp_coop * 2 > n:
        return 'C'
    return 'D'
